values
  ('jwvzuepqqtdprmsayouf','public','0927500b56db78f6729f290bd95443ce',$snapshot${"enums":[{"name":"production_status","schema":"public","values":["waiting","inProgress","paused","completed","problem"]}],"views":[{"name":"employees_view","schema":"public","definition":" SELECT e.id,\n    e.last_name,\n    e.first_name,\n    e.patronymic,\n    e.iin,\n    e.photo_url,\n    e.is_fired,\n    e.comments,\n    e.login,\n    e.password,\n    e.created_at,\n    e.updated_at,\n    COALESCE(array_agg(ep.position_id) FILTER (WHERE (ep.position_id IS NOT NULL)), '{}'::text[]) AS position_ids\n   FROM (employees e\n     LEFT JOIN employee_positions ep ON ((ep.employee_id = e.id)))\n  GROUP BY e.id;"},{"name":"forms_search_view","schema":"public","definition":" SELECT id,\n    series,\n    number,\n    ((series || ' / №'::text) || (number)::text) AS label,\n    size,\n    product_type,\n    colors,\n    image_url\n   FROM forms;"},{"name":"paper_stock_view","schema":"public","definition":" SELECT i.id AS item_id,\n    i.name,\n    i.format,\n    i.grammage,\n    COALESCE(sum(m.qty_m), (0)::numeric) AS qty_m\n   FROM (paper_items i\n     LEFT JOIN paper_moves m ON ((m.item_id = i.id)))\n  GROUP BY i.id, i.name, i.format, i.grammage;"},{"name":"terminals_view","schema":"public","definition":" SELECT t.id,\n    t.name,\n    t.description,\n    t.created_at,\n    t.updated_at,\n    COALESCE(array_agg(tw.workplace_id) FILTER (WHERE (tw.workplace_id IS NOT NULL)), '{}'::text[]) AS workplace_ids\n   FROM (terminals t\n     LEFT JOIN terminal_workplaces tw ON ((tw.terminal_id = t.id)))\n  GROUP BY t.id;"},{"name":"v_materials","schema":"public","definition":" SELECT id,\n    date,\n    supplier,\n    description,\n    unit,\n    quantity,\n    low_threshold,\n    critical_threshold,\n    note,\n    image_url,\n    image_base64,\n    category_id,\n    created_by,\n    created_at,\n    updated_at,\n        CASE\n            WHEN (quantity <= critical_threshold) THEN 'очень низкий'::text\n            WHEN (quantity <= low_threshold) THEN 'низкий'::text\n            ELSE 'норма'::text\n        END AS stock_status\n   FROM materials m;"},{"name":"v_order_plan_stages","schema":"public","definition":" SELECT pp.order_id,\n    o.assignment_id AS order_code,\n    pp.id AS plan_id,\n    pps.id AS plan_stage_id,\n    pps.stage_id,\n    COALESCE(pps.stage_group_key, pps.stage_id) AS stage_group_key,\n    COALESCE(pps.name, COALESCE(w.name, COALESCE(pps.stage_id, ''::text))) AS stage_name,\n    COALESCE(pps.step_no, pps.seq) AS step_no,\n    pps.seq,\n    pps.status,\n    pps.started_at,\n    pps.finished_at,\n    NULL::text AS completed_at,\n    NULL::text AS executor_id,\n    pps.assigned_employee_id\n   FROM (((prod_plans pp\n     JOIN prod_plan_stages pps ON ((pps.plan_id = pp.id)))\n     LEFT JOIN orders o ON ((o.id = pp.order_id)))\n     LEFT JOIN workplaces w ON ((w.id = pps.stage_id)));"},{"name":"v_orders_with_form","schema":"public","definition":" SELECT o.id,\n    o.manager,\n    o.customer,\n    o.order_date,\n    o.due_date,\n    o.is_old_form,\n    o.new_form_no,\n    o.form_id,\n    o.form_series,\n    o.form_code,\n    o.product_name,\n    o.run_size,\n    o.actual_qty,\n    o.width_mm,\n    o.height_mm,\n    o.depth_mm,\n    o.material_name,\n    o.density,\n    o.product_params,\n    o.product,\n    o.leftover_on_stock,\n    o.roll_name,\n    o.width_b,\n    o.length_l,\n    o.handle,\n    o.cardboard,\n    o.makeready,\n    o.val,\n    o.queue_id,\n    o.stage_template_id,\n    o.prod_template_id,\n    o.status,\n    o.assignment_id,\n    o.assignment_created,\n    o.pdf_url,\n    o.created_by,\n    o.created_at,\n    o.updated_at,\n    o.shipped_at,\n    o.shipped_by,\n    o.shipped_qty,\n    o.additional_params,\n    o.material,\n    o.contract_signed,\n    o.payment_done,\n    o.comments,\n    f.series AS forms_series,\n    f.number AS forms_number,\n    f.code AS forms_code,\n    f.status AS forms_status,\n    f.title AS forms_title,\n    f.description AS forms_description,\n    f.image_url AS forms_image_url\n   FROM (orders o\n     LEFT JOIN forms f ON ((f.id = o.form_id)));"},{"name":"v_paints","schema":"public","definition":" SELECT id,\n    date,\n    supplier,\n    description,\n    unit,\n    quantity,\n    low_threshold,\n    critical_threshold,\n    note,\n    image_url,\n    image_base64,\n    color_code,\n    manufacturer,\n    category_id,\n    created_by,\n    created_at,\n    updated_at,\n        CASE\n            WHEN (quantity <= critical_threshold) THEN 'очень низкий'::text\n            WHEN (quantity <= low_threshold) THEN 'низкий'::text\n            ELSE 'норма'::text\n        END AS stock_status\n   FROM paints p;"},{"name":"v_papers","schema":"public","definition":" SELECT id,\n    date,\n    supplier,\n    description,\n    format,\n    grammage,\n    weight,\n    unit,\n    quantity,\n    low_threshold,\n    critical_threshold,\n    note,\n    category_id,\n    created_by,\n    created_at,\n    updated_at,\n        CASE\n            WHEN (quantity <= critical_threshold) THEN 'очень низкий'::text\n            WHEN (quantity <= low_threshold) THEN 'низкий'::text\n            ELSE 'норма'::text\n        END AS stock_status\n   FROM papers p;"},{"name":"v_stationery","schema":"public","definition":" SELECT id,\n    date,\n    supplier,\n    description,\n    unit,\n    quantity,\n    low_threshold,\n    critical_threshold,\n    note,\n    image_url,\n    image_base64,\n    category_id,\n    created_by,\n    created_at,\n    updated_at,\n        CASE\n            WHEN (quantity <= critical_threshold) THEN 'очень низкий'::text\n            WHEN (quantity <= low_threshold) THEN 'низкий'::text\n            ELSE 'норма'::text\n        END AS stock_status\n   FROM stationery s;"},{"name":"vw_pens_movements","schema":"public","definition":" SELECT 'arrival'::text AS kind,\n    a.created_at,\n    a.item_id,\n    a.qty AS delta,\n    a.note,\n    NULL::uuid AS order_id\n   FROM warehouse_pens_arrivals a\nUNION ALL\n SELECT 'writeoff'::text AS kind,\n    w.created_at,\n    w.item_id,\n    (- w.qty) AS delta,\n    w.reason AS note,\n    w.order_id\n   FROM warehouse_pens_writeoffs w\nUNION ALL\n SELECT 'inventory'::text AS kind,\n    i.created_at,\n    i.item_id,\n    i.factual AS delta,\n    i.note,\n    NULL::uuid AS order_id\n   FROM warehouse_pens_inventories i;"},{"name":"workplaces_view","schema":"public","definition":" SELECT id,\n    name,\n    description,\n    has_machine,\n    max_concurrent_workers,\n    unit,\n    created_at,\n    updated_at\n   FROM workplaces w;"}],"schema":"public","columns":[{"table":"actual_qty_formulas","column":"code","default":null,"ordinal":1,"nullable":false,"udt_name":"text","data_type":"text","description":null,"is_generated":"NEVER","generation_expression":null},{"table":"actual_qty_formulas","column":"title","default":null,"ordinal":2,"nullable":false,"udt_name":"text","data_type":"text","description":null,"is_generated":"NEVER","generation_expression":null},{"table":"actual_qty_formulas","column":"description","default":null,"ordinal":3,"nullable":false,"udt_name":"text","data_type":"text","description":null,"is_generated":"NEVER","generation_expression":null},{"table":"actual_qty_formulas","column":"sort_order","default":"0","ordinal":4,"nullable":false,"udt_name":"int4","data_type":"integer","description":null,"is_generated":"NEVER","generation_expression":null},{"table":"analytics","column":"id","default":"gen_random_uuid()","ordinal":1,"nullable":false,"udt_name":"uuid","data_type":"uuid","description":null,"is_generated":"NEVER","generation_expression":null},{"table":"analytics","column":"orderId","default":"''::text","ordinal":2,"nullable":false,"udt_name":"text","data_type":"text","description":null,"is_generated":"NEVER","generation_expression":null},{"table":"analytics","column":"stageId","default":"''::text","ordinal":3,"nullable":false,"udt_name":"text","data_type":"text","description":null,"is_ge